12	export class MotoboyGuard implements CanActivate {
13	  constructor(
14	    private supabase: SupabaseService,
15	    private config: ConfigService,
16	  ) {}
17	
18	  async canActivate(context: ExecutionContext): Promise<boolean> {
19	    const request = context.switchToHttp().getRequest();
20	    const token = request.headers['x-motoboy-token'] as string | undefined;
21	
22	    if (!token) throw new UnauthorizedException('Token de motoboy necessário');
23	
24	    // Login novo: JWT próprio assinado com MOTOBOY_JWT_SECRET.
25	    let payload: (jwt.JwtPayload & MotoboyJwtPayload) | null = null;
26	    try {
27	      const secret = this.config.getOrThrow('MOTOBOY_JWT_SECRET');
28	      payload = jwt.verify(token, secret) as jwt.JwtPayload & MotoboyJwtPayload;
29	    } catch {
30	      payload = null;
31	    }
32	
33	    if (payload) {
34	      const { data } = await this.supabase.client
35	        .from('motoboys')
36	        .select('id, name, is_active, precisa_completar_cadastro, active_session_id, session_expires_at')
37	        .eq('id', payload.motoboyId)
38	        .maybeSingle();
39	
40	      if (!data) throw new UnauthorizedException('Motoboy não encontrado');
41	      if (!data.is_active) throw new ForbiddenException('Conta desativada');
42	
43	      const sessaoValida =
44	        data.active_session_id === payload.sessionId &&
45	        !!data.session_expires_at &&
46	        new Date(data.session_expires_at).getTime() > Date.now();
47	      if (!sessaoValida) throw new UnauthorizedException('Sessão encerrada. Faça login novamente.');
48	
49	      request.motoboyId = data.id;
50	      request.motoboyName = data.name;
