1	import { BadRequestException, ConflictException, ForbiddenException, Injectable, NotFoundException } from '@nestjs/common';
2	import * as bcrypt from 'bcryptjs';
3	import { SupabaseService } from '../supabase/supabase.service';
4	import { ComissaoService } from './comissao.service';
5	import { GeocodingService } from './geocoding.service';
6	import { EstoqueService } from '../estoque/estoque.service';
7	import { SalaoService } from '../salao/salao.service';
8	import { EMAIL_RE, PHONE_RE } from './motoboy-auth.service';
9	
10	export interface MotoboyPeloRestauranteBody {
11	  name?: string;
12	  phone?: string;
13	  email?: string;
14	  password?: string;
15	}
16	
17	const DOC_BUCKET = 'motoboy-documentos';
18	const SIGNED_URL_TTL = 60 * 10; // 10 min
19	
20	@Injectable()
21	export class MotoboyService {
22	  constructor(
23	    private supabase: SupabaseService,
24	    private comissao: ComissaoService,
25	    private geocoding: GeocodingService,
26	    private estoque: EstoqueService,
27	    private salaoService: SalaoService,
28	  ) {}
29	
30	  // Antes de ver/solicitar vaga em qualquer estabelecimento, a plataforma
31	  // (admin) precisa ter revisado e aprovado o cadastro do motoboy.
32	  private async exigirAprovacaoPlataforma(motoboyId: number) {
33	    const { data } = await this.supabase.client
34	      .from('motoboys')
35	      .select('status_plataforma')
36	      .eq('id', motoboyId)
37	      .maybeSingle();
38	    if (data?.status_plataforma !== 'aprovado') {
39	      throw new ForbiddenException('Seu cadastro ainda está em análise pela plataforma. Aguarde a aprovação pra ver os estabelecimentos.');
40	    }
41	  }
42	
43	  private async exigirAfiliacaoAceita(motoboyId: number, restaurantId: number) {
44	    const { data } = await this.supabase.client
45	      .from('motoboy_estabelecimentos')
46	      .select('id, bloqueado')
47	      .eq('motoboy_id', motoboyId)
48	      .eq('restaurant_id', restaurantId)
49	      .eq('status', 'aceito')
50	      .maybeSingle();
51	    if (!data) throw new ForbiddenException('Motoboy não está afiliado a este estabelecimento');
52	    if (data.bloqueado) throw new ForbiddenException('Motoboy está bloqueado neste estabelecimento');
53	  }
54	
55	  // Estabelecimento que optou por entregar por conta própria não deve aparecer
56	  // pra motoboys pegarem pedido sozinhos — o dono ainda pode atribuir manualmente
57	  // como exceção (não passa por aqui).
58	  private async exigirUsaMotoboy(restaurantId: number) {
59	    const { data } = await this.supabase.client
60	      .from('restaurants')
61	      .select('usa_motoboy')
62	      .eq('id', restaurantId)
63	      .maybeSingle();
64	    if (data && data.usa_motoboy === false) {
65	      throw new ForbiddenException('Este estabelecimento faz entregas por conta própria');
66	    }
67	  }
68	
69	  private async signedUrl(path: string | null | undefined): Promise<string | null> {
70	    if (!path) return null;
71	    const { data } = await this.supabase.client.storage.from(DOC_BUCKET).createSignedUrl(path, SIGNED_URL_TTL);
72	    return data?.signedUrl ?? null;
73	  }
74	
75	  // ── Lado restaurante: gestão de afiliados ──────────────────────────
76	
77	  async listar(restaurantId: number) {
78	    const { data, error } = await this.supabase.client
79	      .from('motoboy_estabelecimentos')
80	      .select('bloqueado, motoboy:motoboys(id, name, phone, foto_perfil_url, active_session_id, session_expires_at, criado_por_restaurant_id)')
81	      .eq('restaurant_id', restaurantId)
82	      .eq('status', 'aceito');
83	    if (error) throw error;
84	
85	    const agora = Date.now();
86	    const motoboys = await Promise.all(
87	      (data ?? []).map(async (row: any) => {
88	        const { active_session_id, session_expires_at, ...resto } = row.motoboy ?? {};
89	        return {
90	          ...resto,
91	          foto_perfil_url: await this.signedUrl(resto.foto_perfil_url),
92	          sessao_ativa: !!active_session_id && !!session_expires_at && new Date(session_expires_at).getTime() > agora,
93	          bloqueado: row.bloqueado,
94	          gerenciado_por_mim: resto.criado_por_restaurant_id === restaurantId,
95	        };
96	      }),
97	    );
98	    return { motoboys };
99	  }
100	
101	  // Cadastro direto: o próprio estabelecimento registra um motoboy seu, sem
102	  // passar pelo autocadastro do app + aprovação da plataforma + solicitação de
103	  // afiliação — já nasce aprovado e afiliado (o restaurante está vouching por ele).
104	  async criarPeloRestaurante(restaurantId: number, body: MotoboyPeloRestauranteBody) {
105	    this.validarDadosMotoboy(body, { exigirNome: true, exigirContato: true, exigirSenha: true });
106	
107	    const { data: existente } = await this.supabase.client
108	      .from('motoboys')
109	      .select('id')
110	      .or(`email.eq.${body.email ?? ''},phone.eq.${body.phone ?? ''}`)
111	      .maybeSingle();
112	    if (existente) throw new ConflictException('Já existe um cadastro de motoboy com este telefone ou e-mail');
113	
114	    const passwordHash = await bcrypt.hash(body.password!, 10);
115	    const agora = new Date().toISOString();
116	
117	    const { data: motoboy, error } = await this.supabase.client
118	      .from('motoboys')
119	      .insert({
120	        name: body.name!.trim(),
121	        phone: body.phone || null,
122	        email: body.email || null,
123	        password_hash: passwordHash,
124	        precisa_completar_cadastro: false,
125	        status_plataforma: 'aprovado',
126	        aprovado_em: agora,
127	        criado_por_restaurant_id: restaurantId,
128	      })
129	      .select('id, name, phone, email')
130	      .single();
131	    if (error) throw error;
132	
133	    const { error: afilError } = await this.supabase.client
134	      .from('motoboy_estabelecimentos')
135	      .insert({ motoboy_id: motoboy.id, restaurant_id: restaurantId, status: 'aceito', solicitado_em: agora, respondido_em: agora });
136	    if (afilError) throw afilError;
137	
138	    return { ...motoboy, criado_por_restaurant_id: restaurantId, bloqueado: false, sessao_ativa: false, gerenciado_por_mim: true };
139	  }
140	
141	  private validarDadosMotoboy(
142	    body: MotoboyPeloRestauranteBody,
143	    opts: { exigirNome: boolean; exigirContato: boolean; exigirSenha: boolean },
144	  ) {
145	    if (opts.exigirNome && !body.name?.trim()) throw new BadRequestException('Informe o nome do motoboy');
146	    if (opts.exigirContato && !body.phone && !body.email) throw new BadRequestException('Informe telefone ou e-mail');
147	    if (body.email && !EMAIL_RE.test(body.email)) throw new BadRequestException('E-mail inválido');
148	    if (body.phone && !PHONE_RE.test(body.phone)) throw new BadRequestException('Telefone inválido');
149	    if (opts.exigirSenha && (!body.password || body.password.length < 8)) {
150	      throw new BadRequestException('Senha deve ter no mínimo 8 caracteres');
151	    }
152	    if (!opts.exigirSenha && body.password && body.password.length < 8) {
153	      throw new BadRequestException('Senha deve ter no mínimo 8 caracteres');
154	    }
155	  }
156	
157	  private async exigirMotoboyGerenciadoPeloRestaurante(motoboyId: number, restaurantId: number) {
158	    const { data: mb } = await this.supabase.client
159	      .from('motoboys')
160	      .select('id, criado_por_restaurant_id')
161	      .eq('id', motoboyId)
162	      .maybeSingle();
163	    if (!mb) throw new NotFoundException('Motoboy não encontrado');
164	    if (mb.criado_por_restaurant_id !== restaurantId) {
165	      throw new ForbiddenException('Essa ação só é permitida em motoboys cadastrados diretamente por este estabelecimento');
166	    }
167	  }
168	
169	  async editarPeloRestaurante(motoboyId: number, restaurantId: number, body: MotoboyPeloRestauranteBody) {
170	    await this.exigirMotoboyGerenciadoPeloRestaurante(motoboyId, restaurantId);
171	    this.validarDadosMotoboy(body, { exigirNome: false, exigirContato: false, exigirSenha: false });
172	
173	    const campos: Record<string, any> = {};
174	    if (body.name !== undefined) campos.name = body.name.trim();
175	    if (body.phone !== undefined) campos.phone = body.phone || null;
176	    if (body.email !== undefined) campos.email = body.email || null;
177	    if (body.password) campos.password_hash = await bcrypt.hash(body.password, 10);
178	    if (Object.keys(campos).length === 0) return { ok: true };
179	
180	    const { error } = await this.supabase.client.from('motoboys').update(campos).eq('id', motoboyId);
181	    if (error) throw error;
182	    return { ok: true };
183	  }
184	
185	  // Excluir de verdade só é seguro sem histórico de entregas (motoboy_comissoes
186	  // referencia motoboy_id com ON DELETE CASCADE — apagaria ganhos já registrados).
187	  // Com histórico, orientar a bloquear em vez de excluir.
188	  async excluirPeloRestaurante(motoboyId: number, restaurantId: number) {
189	    await this.exigirMotoboyGerenciadoPeloRestaurante(motoboyId, restaurantId);
190	
191	    const { count } = await this.supabase.client
192	      .from('motoboy_comissoes')
193	      .select('id', { count: 'exact', head: true })
194	      .eq('motoboy_id', motoboyId);
195	    if ((count ?? 0) > 0) {
196	      throw new BadRequestException('Este motoboy já tem entregas registradas — bloqueie em vez de excluir, pra não perder o histórico.');
197	    }
198	
199	    const { error } = await this.supabase.client.from('motoboys').delete().eq('id', motoboyId);
200	    if (error) throw error;
201	    return { ok: true };
202	  }
203	
