445	
446	  async meusPedidos(motoboyId: number) {
447	    const { data, error } = await this.supabase.client
448	      .from('orders')
449	      .select(
450	        'id, total, troco_para, status, payment_method, restaurant_id, created_at, updated_at, motoboy_lat, motoboy_lng, customer_id, delivery_notes, delivery_occurrence',
451	      )
452	      .eq('motoboy_id', motoboyId)
453	      .not('status', 'in', '("delivered","canceled")')
454	      .order('created_at', { ascending: false });
455	    if (error) throw error;
456	
457	    const restIds = [...new Set((data ?? []).map((p) => p.restaurant_id).filter(Boolean))];
458	    const { data: restaurantes } = restIds.length
459	      ? await this.supabase.client.from('restaurants').select('id, name, payment_config').in('id', restIds)
460	      : { data: [] as any[] };
461	    const restMap = Object.fromEntries(
462	      (restaurantes ?? []).map((r: any) => [r.id, { name: r.name, chave_pix: r.payment_config?.chave_pix ?? null }]),
463	    );
464	
465	    const pedidos = await Promise.all(
466	      (data ?? []).map(async (p) => {
467	        const [{ data: c }, { data: itensRaw }] = await Promise.all([
468	          p.customer_id
469	            ? this.supabase.client
470	                .from('customers')
471	                .select('name, phone_e164, address_json')
472	                .eq('id', p.customer_id)
473	                .maybeSingle()
474	            : Promise.resolve({ data: null }),
475	          this.supabase.client
476	            .from('order_items')
477	            .select('id, quantity, unit_price, product_id')
478	            .eq('order_id', p.id),
479	        ]);
480	
481	        let itens = itensRaw ?? [];
482	        if (itens.length > 0) {
483	          const prodIds = itens.map((i: any) => i.product_id);
484	          const { data: prods } = await this.supabase.client
485	            .from('products')
486	            .select('id, name')
487	            .in('id', prodIds);
488	          const prodMap = Object.fromEntries((prods ?? []).map((pr: any) => [pr.id, pr.name]));
489	          itens = itens.map((i: any) => ({ ...i, product_name: prodMap[i.product_id] ?? `Produto #${i.product_id}` }));
490	        }
491	
492	        return { ...p, cliente: c, itens, restaurante: restMap[p.restaurant_id] ?? null };
493	      }),
494	    );
495	    return { pedidos };
496	  }
