508	  async confirmarEntrega(
509	    pedidoId: number,
510	    motoboyId: number,
511	    entregaPagamento?: { metodo: string; dinheiro?: number; pix?: number },
512	  ) {
513	    const { data: pedido } = await this.supabase.client
514	      .from('orders')
515	      .select('id, status, restaurant_id, total, frete_cobrado, customer_id, payment_method')
516	      .eq('id', pedidoId)
517	      .eq('motoboy_id', motoboyId)
518	      .maybeSingle();
519	    if (!pedido) throw new NotFoundException('Pedido não encontrado ou não atribuído a você');
520	
521	    const updatePayload: Record<string, any> = { status: 'delivered', updated_at: new Date().toISOString() };
522	    if (entregaPagamento) updatePayload.entrega_pagamento = entregaPagamento;
523	
524	    const { error } = await this.supabase.client
525	      .from('orders')
526	      .update(updatePayload)
527	      .eq('id', pedidoId);
528	    if (error) throw error;
529	
530	    // Registrar entrada(s) no caixa aberto
531	    if (entregaPagamento && pedido.restaurant_id) {
532	      const { data: caixa } = await this.supabase.client
533	        .from('caixas')
534	        .select('id, entradas')
535	        .eq('restaurant_id', pedido.restaurant_id)
536	        .eq('status', 'aberto')
537	        .maybeSingle();
538	
539	      if (caixa) {
540	        const entradas = (caixa.entradas ?? []) as any[];
541	        const novas: any[] = [];
542	        const agora = new Date().toISOString();
543	
544	        if ((entregaPagamento.dinheiro ?? 0) > 0) {
545	          novas.push({
546	            descricao: `Entrega pedido #${pedidoId} — dinheiro`,
547	            valor: entregaPagamento.dinheiro,
548	            meio: 'dinheiro',
549	            criado_em: agora,
550	          });
551	        }
552	        if ((entregaPagamento.pix ?? 0) > 0) {
553	          novas.push({
554	            descricao: `Entrega pedido #${pedidoId} — PIX`,
555	            valor: entregaPagamento.pix,
556	            meio: 'pix',
557	            criado_em: agora,
558	          });
559	        }
560	
561	        if (novas.length > 0) {
562	          await this.supabase.client
563	            .from('caixas')
564	            .update({ entradas: [...entradas, ...novas] })
565	            .eq('id', caixa.id);
566	        }
567	      }
568	    }
569	
570	    // Pedido já veio com "pagamento em dinheiro" escolhido no checkout (não é o motoboy
571	    // reportando o que cobrou na hora — isso é o `entregaPagamento` acima) — sem isso o
572	    // caixa físico nunca credita essa venda, só o fundo inicial (mesmo bug do salão).
573	    if (!entregaPagamento?.dinheiro && pedido.payment_method === 'cash' && pedido.restaurant_id) {
574	      await this.salaoService.registrarEntradaCaixa(pedido.restaurant_id, `Venda delivery em dinheiro - Pedido #${pedidoId}`, pedido.total, 'venda_dinheiro');
575	    }
576	
577	    // Calcula e registra a comissão do motoboy (idempotente — UNIQUE(pedido_id))
578	    await this.comissao.registrarComissaoEntrega(pedido, motoboyId);
579	
580	    return { ok: true, pedido_id: pedidoId, status: 'delivered' };
581	  }
582	
583	  // Dono do restaurante marca um pedido como entregue pela própria loja, sem motoboy.
584	  // Só permitido se não houver motoboy atribuído (evita marcar como entrega própria
585	  // um pedido que já está com um motoboy de verdade).
586	  async entregarProprio(
587	    pedidoId: number,
588	    restaurantId: number,
589	    entregaPagamento?: { metodo: string; dinheiro?: number; pix?: number },
590	  ) {
591	    const { data: pedido } = await this.supabase.client
592	      .from('orders')
593	      .select('id, status, restaurant_id, motoboy_id, total, payment_method')
594	      .eq('id', pedidoId)
595	      .eq('restaurant_id', restaurantId)
596	      .maybeSingle();
597	    if (!pedido) throw new NotFoundException('Pedido não encontrado neste restaurante');
598	    if (pedido.motoboy_id) throw new BadRequestException('Pedido já está atribuído a um motoboy');
599	
600	    const updatePayload: Record<string, any> = {
601	      status: 'delivered',
602	      entrega_propria: true,
603	      updated_at: new Date().toISOString(),
604	    };
605	    if (entregaPagamento) updatePayload.entrega_pagamento = entregaPagamento;
606	
607	    const { error } = await this.supabase.client.from('orders').update(updatePayload).eq('id', pedidoId);
608	    if (error) throw error;
609	
610	    if (entregaPagamento) {
611	      const { data: caixa } = await this.supabase.client
612	        .from('caixas')
613	        .select('id, entradas')
614	        .eq('restaurant_id', restaurantId)
615	        .eq('status', 'aberto')
616	        .maybeSingle();
617	
618	      if (caixa) {
619	        const entradas = (caixa.entradas ?? []) as any[];
620	        const novas: any[] = [];
621	        const agora = new Date().toISOString();
622	
623	        if ((entregaPagamento.dinheiro ?? 0) > 0) {
624	          novas.push({
625	            descricao: `Entrega própria pedido #${pedidoId} — dinheiro`,
626	            valor: entregaPagamento.dinheiro,
627	            meio: 'dinheiro',
628	            criado_em: agora,
629	          });
630	        }
631	        if ((entregaPagamento.pix ?? 0) > 0) {
632	          novas.push({
633	            descricao: `Entrega própria pedido #${pedidoId} — PIX`,
634	            valor: entregaPagamento.pix,
635	            meio: 'pix',
636	            criado_em: agora,
637	          });
638	        }
639	
640	        if (novas.length > 0) {
641	          await this.supabase.client.from('caixas').update({ entradas: [...entradas, ...novas] }).eq('id', caixa.id);
642	        }
643	      }
644	    }
645	
646	    // Idem confirmarEntrega: pedido pago em dinheiro no checkout, sem o dono reportar
647	    // via entregaPagamento — precisa creditar o caixa físico do mesmo jeito.
648	    if (!entregaPagamento?.dinheiro && pedido.payment_method === 'cash') {
649	      await this.salaoService.registrarEntradaCaixa(restaurantId, `Venda delivery em dinheiro (entrega própria) - Pedido #${pedidoId}`, pedido.total, 'venda_dinheiro');
650	    }
651	
652	    return { ok: true, pedido_id: pedidoId, status: 'delivered', entrega_propria: true };
653	  }
