  async pegarPedido(pedidoId: number, motoboyId: number) {
    const { data: pedido } = await this.supabase.client
      .from('orders')
      .select('id, restaurant_id')
      .eq('id', pedidoId)
      .maybeSingle();
    if (!pedido) throw new NotFoundException('Pedido não encontrado');
    await this.exigirAfiliacaoAceita(motoboyId, pedido.restaurant_id);
    await this.exigirUsaMotoboy(pedido.restaurant_id);

    const { data, error } = await this.supabase.client
      .from('orders')
      .update({ motoboy_id: motoboyId, status: 'motoboy_collecting', updated_at: new Date().toISOString() })
      .eq('id', pedidoId)
      .eq('restaurant_id', pedido.restaurant_id)
      .eq('status', 'ready')
      .is('motoboy_id', null)
      .select('id');
    if (error) throw error;
    if (!data || data.length === 0) {
      throw new ConflictException('Pedido já foi pego por outro motoboy ou não está disponível');
    }
    return { ok: true, pedido_id: pedidoId, status: 'motoboy_collecting' };
  }

  async reivindicarPedido(pedidoId: number, motoboyId: number) {
    const { data: pedido } = await this.supabase.client
      .from('orders')
      .select('id, restaurant_id')
      .eq('id', pedidoId)
      .maybeSingle();
    if (!pedido) throw new NotFoundException('Pedido não encontrado');
    await this.exigirAfiliacaoAceita(motoboyId, pedido.restaurant_id);
    await this.exigirUsaMotoboy(pedido.restaurant_id);

    const { data, error } = await this.supabase.client
      .from('orders')
      .update({ motoboy_id: motoboyId, status: 'motoboy_collecting', updated_at: new Date().toISOString() })
      .eq('id', pedidoId)
      .eq('restaurant_id', pedido.restaurant_id)
      .in('status', ['ready', 'preparing', 'confirmed'])
      .is('motoboy_id', null)
      .select('id');
    if (error) throw error;
    if (!data || data.length === 0) {
      throw new ConflictException('Pedido não encontrado, já foi atribuído ou não está disponível');
    }
    return { ok: true, pedido_id: pedidoId, status: 'motoboy_collecting' };
  }

  async confirmarColeta(pedidoId: number, motoboyId: number, barcode: string) {
    const expected = String(pedidoId).padStart(8, '0');
    const scanned = barcode.replace(/\D/g, '').padStart(8, '0');
    if (scanned !== expected) {
      throw new BadRequestException('Código de barras não confere com este pedido');
    }

    const { data: pedido } = await this.supabase.client
      .from('orders')
      .select('id, total, troco_para, payment_method, restaurant_id')
      .eq('id', pedidoId)
      .eq('motoboy_id', motoboyId)
      .eq('status', 'motoboy_collecting')
      .maybeSingle();
    if (!pedido) throw new ConflictException('Pedido não está aguardando coleta ou não pertence a você');

    const { error } = await this.supabase.client
      .from('orders')
      .update({ status: 'out_for_delivery', updated_at: new Date().toISOString() })
      .eq('id', pedidoId);
    if (error) throw error;

    const trocoValor = pedido.payment_method === 'cash' && pedido.troco_para > pedido.total
      ? Number(pedido.troco_para) - Number(pedido.total)
      : 0;
    if (trocoValor > 0) {
      const { data: caixa } = await this.supabase.client
        .from('caixas')
        .select('id, saidas')
        .eq('restaurant_id', pedido.restaurant_id)
        .eq('status', 'aberto')
        .maybeSingle();
      if (caixa) {
        const saidas = (caixa.saidas ?? []) as any[];
        const novaSaida = {
          descricao: `Troco pedido #${pedidoId}`,
          valor: trocoValor,
          meio: 'dinheiro',
          criado_em: new Date().toISOString(),
        };
        await this.supabase.client
          .from('caixas')
          .update({ saidas: [...saidas, novaSaida] })
          .eq('id', caixa.id);
      }
    }

    return { ok: true, pedido_id: pedidoId, status: 'out_for_delivery', troco: trocoValor };
  }

  async uploadComprovante(pedidoId: number, motoboyId: number, base64: string) {
    const { data: pedido } = await this.supabase.client
      .from('orders')
      .select('id')
      .eq('id', pedidoId)
      .eq('motoboy_id', motoboyId)
      .maybeSingle();
    if (!pedido) throw new NotFoundException('Pedido não encontrado ou não atribuído a você');

    const matches = base64.match(/^data:(image\/\w+);base64,(.+)$/);
    const mimeType = matches ? matches[1] : 'image/jpeg';
    const raw = matches ? matches[2] : base64;
    const buffer = Buffer.from(raw, 'base64');
    const ext = mimeType === 'image/png' ? 'png' : 'jpg';
    const path = `pedido-${pedidoId}-${Date.now()}.${ext}`;

    const { error: uploadError } = await this.supabase.client.storage
      .from('comprovantes-pix')
      .upload(path, buffer, { contentType: mimeType, upsert: true });
    if (uploadError) throw uploadError;

    const { data: { publicUrl } } = this.supabase.client.storage
      .from('comprovantes-pix')
      .getPublicUrl(path);

    await this.supabase.client
      .from('orders')
      .update({ comprovante_pix_url: publicUrl, updated_at: new Date().toISOString() })
      .eq('id', pedidoId);

    return { url: publicUrl };
  }

  private async limiteRevisoesPlataforma(): Promise<number> {
    const { data } = await this.supabase.client
      .from('platform_settings').select('config').eq('id', 1).maybeSingle();
    return (data?.config as Record<string, any>)?.motoboy_limite_revisoes ?? 2;
  }

  async infoMotoboy(motoboyId: number) {
    const { data: mb } = await this.supabase.client
      .from('motoboys')
      .select(
        'id, name, phone, email, foto_perfil_url, precisa_completar_cadastro, status_plataforma, motivo_recusa_plataforma, revisoes_solicitadas',
      )
      .eq('id', motoboyId)
      .maybeSingle();
    if (!mb) return null;

    const { afiliacoes } = await this.minhasAfiliacoes(motoboyId);

    return {
      ...mb,
      foto_perfil_url: await this.signedUrl(mb.foto_perfil_url),
      estabelecimentos: afiliacoes.filter((a: any) => a.status === 'aceito').map((a: any) => a.restaurant),
      limite_revisoes_plataforma: await this.limiteRevisoesPlataforma(),
    };
  }

  // Motoboy recusado pede reavaliação — reabre como pendente. Limitado (config
  // do admin) pra não virar loop infinito de recusa/revisão.
  async solicitarRevisaoPlataforma(motoboyId: number) {
    const { data: mb } = await this.supabase.client
      .from('motoboys')
      .select('status_plataforma, revisoes_solicitadas')
      .eq('id', motoboyId)
      .maybeSingle();
    if (!mb) throw new NotFoundException('Motoboy não encontrado');
    if (mb.status_plataforma !== 'recusado') {
      throw new BadRequestException('Só é possível pedir revisão de um cadastro recusado');
    }

    const limite = await this.limiteRevisoesPlataforma();
    if (mb.revisoes_solicitadas >= limite) {
      throw new ForbiddenException('Limite de pedidos de revisão atingido. Entre em contato com o suporte.');
    }

    const { data, error } = await this.supabase.client
      .from('motoboys')
      .update({
        status_plataforma: 'pendente',
        motivo_recusa_plataforma: null,
        revisoes_solicitadas: mb.revisoes_solicitadas + 1,
      })
      .eq('id', motoboyId)
      .select('id, status_plataforma, revisoes_solicitadas')
      .maybeSingle();
    if (error) throw error;
    return data;
  }

  // ── Ganhos / comissões ───────────────────────────────────────────────

  async ganhosResumo(motoboyId: number) {
    const { data, error } = await this.supabase.client
      .from('motoboy_comissoes')
      .select('restaurant_id, comissao_valor, restaurant:restaurants(name)')
      .eq('motoboy_id', motoboyId);
    if (error) throw error;

    const porRestaurante = new Map<number, { restaurant_id: number; nome: string; total: number; entregas: number }>();
    for (const row of data ?? []) {
      const atual = porRestaurante.get(row.restaurant_id) ?? {
        restaurant_id: row.restaurant_id,
        nome: (row as any).restaurant?.name ?? `Estabelecimento #${row.restaurant_id}`,
        total: 0,
        entregas: 0,
      };
      atual.total += Number(row.comissao_valor);
      atual.entregas += 1;
      porRestaurante.set(row.restaurant_id, atual);
    }

    const resumo = [...porRestaurante.values()].sort((a, b) => b.total - a.total);
    const totalGeral = resumo.reduce((acc, r) => acc + r.total, 0);
    return { resumo, total_geral: totalGeral };
  }

  async ganhosHistorico(motoboyId: number, restaurantId?: number) {
    let query = this.supabase.client
      .from('motoboy_comissoes')
      .select('id, restaurant_id, pedido_id, tipo, distancia_km, frete_repassado, valor_base, comissao_valor, status, criado_em, restaurant:restaurants(name)')
      .eq('motoboy_id', motoboyId)
      .order('criado_em', { ascending: false })
      .limit(100);
    if (restaurantId) query = query.eq('restaurant_id', restaurantId);

    const { data, error } = await query;
    if (error) throw error;
    return { historico: data ?? [] };
  }

  // ── Admin: aprovação de cadastro de motoboy pela plataforma ─────────

  async listarMotoboysAdmin(status?: string) {
    let query = this.supabase.client
      .from('motoboys')
      .select('id, name, phone, email, foto_perfil_url, status_plataforma, motivo_recusa_plataforma, aprovado_em, created_at')
      .order('created_at', { ascending: false });
    if (status) query = query.eq('status_plataforma', status);

    const { data, error } = await query;
    if (error) throw error;

    return {
      motoboys: await Promise.all(
        (data ?? []).map(async (m: any) => ({ ...m, foto_perfil_url: await this.signedUrl(m.foto_perfil_url) })),
      ),
    };
  }

  async detalheMotoboyAdmin(motoboyId: number) {
    const { data: mb, error } = await this.supabase.client
      .from('motoboys')
      .select(
        'id, name, phone, email, foto_perfil_url, documento_frente_url, documento_verso_url, comprovante_endereco_url, status_plataforma, motivo_recusa_plataforma, aprovado_em, created_at, revisoes_solicitadas',
      )
      .eq('id', motoboyId)
      .maybeSingle();
    if (error) throw error;
    if (!mb) throw new NotFoundException('Motoboy não encontrado');

    return {
      ...mb,
      foto_perfil_url: await this.signedUrl(mb.foto_perfil_url),
      documento_frente_url: await this.signedUrl(mb.documento_frente_url),
      documento_verso_url: await this.signedUrl(mb.documento_verso_url),
      comprovante_endereco_url: await this.signedUrl(mb.comprovante_endereco_url),
    };
  }

  async aprovarMotoboyAdmin(motoboyId: number) {
    const { data, error } = await this.supabase.client
      .from('motoboys')
      .update({ status_plataforma: 'aprovado', motivo_recusa_plataforma: null, aprovado_em: new Date().toISOString() })
      .eq('id', motoboyId)
      .select('id, name, status_plataforma')
      .maybeSingle();
    if (error) throw error;
    if (!data) throw new NotFoundException('Motoboy não encontrado');
    return data;
  }

  async recusarMotoboyAdmin(motoboyId: number, motivo?: string) {
    const { data, error } = await this.supabase.client
      .from('motoboys')
      .update({ status_plataforma: 'recusado', motivo_recusa_plataforma: motivo ?? null, aprovado_em: null })
      .eq('id', motoboyId)
      .select('id, name, status_plataforma')
      .maybeSingle();
    if (error) throw error;
    if (!data) throw new NotFoundException('Motoboy não encontrado');
    return data;
  }
}

