1	import React, { useState } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import Icon from '../../components/AppIcon';
4	import { cadastro, setMotoboyToken, arquivoParaBase64 } from '../../services/motoboyAuthService';
5	import { useAuth } from '../../contexts/AuthContext';
6	
7	const CAMPOS_ARQUIVO = [
8	  { name: 'foto_perfil', label: 'Foto de perfil', obrigatorio: true, icon: 'User', accept: 'image/*' },
9	  { name: 'documento_frente', label: 'Documento com foto (CNH ou RG)', obrigatorio: true, icon: 'IdCard', accept: 'image/*,application/pdf' },
10	  { name: 'documento_verso', label: 'Verso do documento (opcional)', obrigatorio: false, icon: 'IdCard', accept: 'image/*,application/pdf' },
11	  { name: 'comprovante_endereco', label: 'Comprovante de endereço', obrigatorio: true, icon: 'FileText', accept: 'image/*,application/pdf' },
12	];
13	
14	const MotoboyCadastro = () => {
15	  const navigate = useNavigate();
16	  const { refreshUserProfile } = useAuth();
17	  const [form, setForm] = useState({ name: '', phone: '', email: '', password: '' });
18	  const [arquivos, setArquivos] = useState({});
19	  const [previews, setPreviews] = useState({});
20	  const [erro, setErro] = useState(null);
21	  const [enviando, setEnviando] = useState(false);
22	
23	  const set = (k, v) => setForm((f) => ({ ...f, [k]: v }));
24	
25	  const handleArquivo = async (campo, file) => {
26	    if (!file) return;
27	    const base64 = await arquivoParaBase64(file);
28	    setArquivos((a) => ({ ...a, [campo]: base64 }));
29	    setPreviews((p) => ({ ...p, [campo]: file.name }));
30	  };
31	
32	  const handleSubmit = async (e) => {
33	    e.preventDefault();
34	    setErro(null);
35	
36	    for (const campo of CAMPOS_ARQUIVO) {
37	      if (campo.obrigatorio && !arquivos[campo.name]) {
38	        setErro(`Envie: ${campo.label}`);
39	        return;
40	      }
41	    }
42	
43	    setEnviando(true);
44	    try {
45	      const { token } = await cadastro({ ...form, ...arquivos });
46	      setMotoboyToken(token);
47	      refreshUserProfile(); // se era cliente logado, o role virou 'motoboy' no banco
48	      navigate('/motoboy');
49	    } catch (err) {
50	      setErro(err.message);
51	    } finally {
52	      setEnviando(false);
53	    }
54	  };
55	
56	  return (
57	    <div className="min-h-screen bg-[#F4F4F5] dark:bg-[#18181B] flex items-center justify-center p-4">
58	      <div className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] p-6 w-full max-w-md shadow-lg my-8">
59	        <button type="button" onClick={() => navigate('/')}
60	          className="flex items-center gap-1.5 text-sm text-[#71717A] dark:text-[#A1A1AA] hover:text-[#27272A] dark:hover:text-[#F4F4F5] mb-4">
61	          <Icon name="ArrowLeft" size={16} />
62	          Voltar
63	        </button>
64	        <div className="text-center mb-6">
65	          <div className="w-14 h-14 bg-[#FF441F]/10 rounded-2xl flex items-center justify-center mx-auto mb-3">
66	            <Icon name="Bike" size={28} className="text-[#FF441F]" />
67	          </div>
68	          <h1 className="text-lg font-black text-[#18181B] dark:text-[#F4F4F5]">Cadastro de Entregador</h1>
69	          <p className="text-sm text-[#71717A] dark:text-[#A1A1AA] mt-1">Depois de cadastrado, você escolhe pra quais estabelecimentos quer entregar</p>
70	        </div>
71	
72	        <form onSubmit={handleSubmit} className="space-y-3">
73	          <input required value={form.name} onChange={(e) => set('name', e.target.value)}
74	            placeholder="Nome completo"
75	            className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-[#FF441F]" />
76	          <input required value={form.phone} onChange={(e) => set('phone', e.target.value)}
77	            placeholder="Telefone (WhatsApp)"
78	            className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-[#FF441F]" />
79	          <input required type="email" value={form.email} onChange={(e) => set('email', e.target.value)}
80	            placeholder="E-mail"
81	            className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-[#FF441F]" />
82	          <input required type="password" minLength={6} value={form.password} onChange={(e) => set('password', e.target.value)}
83	            placeholder="Senha (mínimo 6 caracteres)"
84	            className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-[#FF441F]" />
85	
86	          <div className="pt-2 space-y-2.5">
87	            {CAMPOS_ARQUIVO.map((campo) => (
88	              <label key={campo.name}
89	                className="flex items-center gap-3 border border-dashed border-[#E4E4E7] dark:border-[#3F3F46] rounded-xl px-3 py-2.5 cursor-pointer hover:border-[#FF441F]/50 transition-colors">
90	                <Icon name={previews[campo.name] ? 'CheckCircle2' : campo.icon}
91	                  size={18} className={previews[campo.name] ? 'text-green-600 dark:text-green-400' : 'text-[#71717A] dark:text-[#A1A1AA]'} />
92	                <span className="flex-1 text-sm text-[#27272A] dark:text-[#F4F4F5] truncate">
93	                  {previews[campo.name] ?? `${campo.label}${campo.obrigatorio ? ' *' : ''}`}
94	                </span>
95	                <input type="file" accept={campo.accept} className="hidden"
96	                  onChange={(e) => handleArquivo(campo.name, e.target.files?.[0])} />
97	              </label>
98	            ))}
99	          </div>
100	
101	          {erro && <p className="text-xs text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-950/40 rounded-lg px-3 py-2">{erro}</p>}
